def monotonic(l):
    """
    Unified function for lists and strings:

    For lists:
      - Return (True, sum) if elements are strictly monotonically increasing or decreasing,
        without duplicates.
      - Return False if there are duplicates or not monotonic.
      - sum is an integer sum of the elements.

    For strings:
      - Return (True, original_string) if characters are strictly increasing or decreasing alphabetically,
        without duplicates.
      - Return False if there are duplicates or not monotonic.
      - sum is the original string.

    Restrictions:
      - No loops
      - No built-in sorting methods

    >>> monotonic([1, 2, 4, 20])
    (True, 27)
    >>> monotonic([1, 1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    (True, -5)
    >>> monotonic("abcd")
    (True, 'abcd')
    >>> monotonic("abca")
    False
    >>> monotonic("dcba")
    (True, 'dcba')
    """

    def has_duplicates(seq):
        if len(seq) <= 1:
            return False
        if seq[0] in seq[1:]:
            return True
        return has_duplicates(seq[1:])

    def strictly_increasing(seq):
        if len(seq) <= 1:
            return True
        if not seq[0] < seq[1]:
            return False
        return strictly_increasing(seq[1:])

    def strictly_decreasing(seq):
        if len(seq) <= 1:
            return True
        if not seq[0] > seq[1]:
            return False
        return strictly_decreasing(seq[1:])

    def recursive_sum(seq):
        if not seq:
            return 0
        return seq[0] + recursive_sum(seq[1:])
    if isinstance(l, list):
        if has_duplicates(l):
            return False
        if strictly_increasing(l) or strictly_decreasing(l):
            return (True, recursive_sum(l))
        else:
            return False
    elif isinstance(l, str):
        if has_duplicates(l):
            return False
        if strictly_increasing(l) or strictly_decreasing(l):
            return (True, l)
        else:
            return False
    else:
        raise TypeError('Input must be a list or a string')
