def process_paren_groups(text):
    """ The input to this routine is a piece of data composed of several groups of parentheses separated by whitespace.
    For each group, return an indication of the deepest nesting level present.
    E.g. (()()) has two levels while ((())) has three.

    >>> process_paren_groups('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """

    def parse_nested_parens(group):
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif char == ')':
                current_depth -= 1
                if current_depth < 0:
                    raise ValueError(f'Unbalanced parentheses in group: {group}')
            else:
                raise ValueError(f'Invalid character {char} in group: {group}')
        if current_depth != 0:
            raise ValueError(f'Unbalanced parentheses in group: {group}')
        return max_depth
    groups = text.split()
    return [parse_nested_parens(group) for group in groups]
```

