def prime_length(string):
    """
    Returns True if and only if the length of the input string is a prime number.

    Examples:
    prime_length('Hello') == True  # length 5, prime
    prime_length('abcdcba') == True  # length 7, prime
    prime_length('kittens') == True  # length 7, prime
    prime_length('orange') == False  # length 6, not prime
    """

    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True
    return is_prime(len(string))
