def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.

    For negative numbers, the sorting key is computed by:
    - taking the digits without the minus sign,
    - negating only the first digit,
    - leaving the rest positive,
    - then summing these values.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """

    def key(n):
        s = str(abs(n))
        if n < 0:
            digits = [-int(s[0])] + [int(d) for d in s[1:]]
            return sum(digits)
        else:
            return sum((int(d) for d in s))
    return sorted(nums, key=key)
