def next_smallest_palindrome(num: int) -> int:
    """
    Returns the smallest palindrome strictly greater than the input number.
    """

    def is_all_nines(n_str):
        return all((ch == '9' for ch in n_str))

    def make_palindrome(left, middle, odd_length):
        if odd_length:
            return left + middle + left[::-1]
        else:
            return left + left[::-1]
    s = str(num)
    length = len(s)
    if is_all_nines(s):
        return int('1' + '0' * (length - 1) + '1')
    odd_length = length % 2 != 0
    mid = length // 2
    if odd_length:
        left = s[:mid]
        middle = s[mid]
        right = s[mid + 1:]
    else:
        left = s[:mid]
        middle = ''
        right = s[mid:]
    palindrome = make_palindrome(left, middle, odd_length)
    palindrome_num = int(palindrome)
    if palindrome_num > num:
        return palindrome_num
    if odd_length:
        left_middle = left + middle
        incremented = str(int(left_middle) + 1)
        if len(incremented) > len(left_middle):
            return int('1' + '0' * (length - 1) + '1')
        new_left = incremented[:-1]
        new_middle = incremented[-1]
        palindrome = make_palindrome(new_left, new_middle, True)
    else:
        incremented = str(int(left) + 1)
        if len(incremented) > len(left):
            return int('1' + '0' * (length - 1) + '1')
        palindrome = make_palindrome(incremented, '', False)
    return int(palindrome)
