def find_solution(a, b, n):
    """
    Find non-negative integers x, y such that a*x + b*y = n,
    with x minimized among all non-negative solutions.
    If no such solution exists, return "No solution".

    Parameters:
        a (int): coefficient of x
        b (int): coefficient of y
        n (int): target integer

    Returns:
        tuple (x, y) of integers if solution exists, else "No solution"
    """
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return 'No solution'
    if a == 0:
        if b == 0:
            return 'No solution'
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return 'No solution'
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return 'No solution'
    max_x = n // a if a > 0 else 0
    for x in range(max_x + 1):
        remainder = n - a * x
        if remainder < 0:
            break
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
    return 'No solution'
```

