def get_total_number_of_sequences(n, max_element):
    """
    Returns the total number of sequences of length n such that:
    - The first element is any integer from 1 to max_element.
    - Each next element is greater than or equal to twice the previous element.

    Parameters:
    n (int): length of the sequence
    max_element (int): maximum allowed value for any element

    Returns:
    int: total number of valid sequences
    """
    if n == 0:
        return 0
    if n == 1:
        return max_element
    dp = [0] * (max_element + 1)
    for x in range(1, max_element + 1):
        dp[x] = 1
    for length in range(2, n + 1):
        new_dp = [0] * (max_element + 1)
        for x in range(1, max_element + 1):
            next_min = 2 * x
            if next_min > max_element:
                new_dp[x] = 0
            else:
                pass
        prefix_sum = [0] * (max_element + 2)
        for i in range(1, max_element + 1):
            prefix_sum[i] = prefix_sum[i - 1] + dp[i]
        for x in range(1, max_element + 1):
            next_min = 2 * x
            if next_min > max_element:
                new_dp[x] = 0
            else:
                new_dp[x] = prefix_sum[max_element] - prefix_sum[next_min - 1]
        dp = new_dp
    return sum(dp[1:])
