def find_solution(a, b, n):
    """
    Finds integers x, y such that:
        a*x + b*y = n,
    with x >= 0 (x non-negative integer) and y any integer.

    Returns:
        (x, y) tuple if a solution exists,
        None if no solution exists under the constraints.
    """

    def extended_gcd(aa, bb):
        """Extended Euclidean Algorithm.
        Returns (g, x, y) such that a*x + b*y = g = gcd(a, b)
        """
        if bb == 0:
            return (aa, 1, 0)
        else:
            g, x1, y1 = extended_gcd(bb, aa % bb)
            x = y1
            y = x1 - aa // bb * y1
            return (g, x, y)
    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None
    x0 *= n // g
    y0 *= n // g
    b_div = b // g
    a_div = a // g
    if b_div == 0:
        if n % a == 0:
            x_candidate = n // a
            if x_candidate >= 0:
                return (x_candidate, 0)
        return None
    import math
    if b_div > 0:
        k_min = math.ceil(-x0 / b_div)
        k = k_min
    else:
        k_max = math.floor(-x0 / b_div)
        k = k_max
    x = x0 + k * b_div
    y = y0 - k * a_div
    if x >= 0:
        return (x, y)
    else:
        return None
