def substract_elements(a, b):
    """
    Recursively subtract corresponding elements in nested collections a and b,
    preserving the nested structure.

    Args:
        a, b: Nested collections (lists or tuples) of the same structure, or numeric values.

    Returns:
        A nested collection of the same structure with differences of corresponding elements.

    Raises:
        ValueError: if the structures of a and b do not match.
    """
    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        if len(a) != len(b):
            raise ValueError('Structures do not match: different lengths')
        result = [substract_elements(x, y) for x, y in zip(a, b)]
        return type(a)(result)
    else:
        try:
            return a - b
        except TypeError:
            raise ValueError(f'Cannot subtract elements {a} and {b}')
