def dif_Square(n: int) -> bool:
    """
    Check whether the integer n can be expressed as a difference of two squares:
    n = a^2 - b^2 for some integers a and b.

    Returns True if such a and b exist, otherwise False.
    """
    if n == 0:
        return True
    abs_n = abs(n)
    for x in range(1, int(abs_n ** 0.5) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            if x % 2 == y % 2:
                if x * y == abs_n:
                    a = (y + x) // 2
                    b = (y - x) // 2
                    if n > 0:
                        if a * a - b * b == n:
                            return True
                    elif b * b - a * a == n:
                        return True
    return False
