    Find non-negative integers x, y such that a*x + b*y = n.
    Returns a tuple (x, y) if a solution exists, otherwise None.
    """
    if a <= 0 or b <= 0 or n < 0:
        return None
    max_x = n // a
    for x in range(max_x + 1):
        remainder = n - a * x
        if remainder < 0:
            break
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
    return None
