def dict_depth(d):
    """
    Compute the depth of a dictionary, counting only nested dictionaries as increasing depth.
    Nested lists or tuples containing dictionaries do not increase depth beyond the dictionaries' own nesting.
    """
    if not isinstance(d, dict):
        return 0
    max_depth = 0
    for v in d.values():
        if isinstance(v, dict):
            depth = dict_depth(v)
            if depth > max_depth:
                max_depth = depth
        elif isinstance(v, (list, tuple)):
            inner_max = 0
            for item in v:
                if isinstance(item, dict):
                    depth = dict_depth(item)
                    if depth > inner_max:
                        inner_max = depth
            if inner_max > max_depth:
                max_depth = inner_max
    return 1 + max_depth
```

