def find_Max(arr):
    """
    Finds the maximum element in a sorted and rotated array.

    Parameters:
    arr (list): A list of integers which is sorted and then rotated.

    Returns:
    int: The maximum element in the array.
    """
    if not arr:
        raise ValueError('Array is empty')
    low, high = (0, len(arr) - 1)
    if arr[low] < arr[high]:
        return arr[high]
    while low <= high:
        mid = (low + high) // 2
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]
        if arr[mid] >= arr[low]:
            low = mid + 1
        else:
            high = mid - 1
    return arr[0]
