def text_match_two_three(text):
    """
    Finds substrings in the input text where a pattern occurs exactly two or three times consecutively.
    The pattern to match is any substring repeated exactly 2 or 3 times in a row.

    Returns:
        - A list of matching substrings if found (each substring repeated 2 or 3 times).
        - The string 'Not matched!' if no such pattern is found.
    """
    import re
    matches = set()
    n = len(text)
    for length in range(1, n // 2 + 1):
        for start in range(n - length * 2 + 1):
            sub = text[start:start + length]
            if start + length * 2 <= n and text[start:start + length * 2] == sub * 2:
                matches.add(sub * 2)
            if start + length * 3 <= n and text[start:start + length * 3] == sub * 3:
                matches.add(sub * 3)
    if matches:
        return sorted(matches)
    else:
        return 'Not matched!'
