def dif_Square(n):
    """
    Check if the given number n can be expressed as a difference of two squares:
    n = a^2 - b^2 for some integers a and b.

    Returns True if such integers exist, False otherwise.
    """
    if not isinstance(n, (int, float)):
        return False
    if isinstance(n, float):
        if not n.is_integer():
            return False
        n = int(n)
    if n == 0:
        return True
    abs_n = abs(n)
    for x in range(1, int(abs_n ** 0.5) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            for a, b in [(x, y), (-x, -y)]:
                s = (b + a) / 2
                t = (b - a) / 2
                if s.is_integer() and t.is_integer():
                    return True
    return False
