def find_solution(a, b, n):
    """
    Finds the first non-negative integer solution (x, y) to the equation:
        a*x + b*y = n
    Returns:
        A tuple formatted as ('x = ', x, ', y = ', y) for the first valid solution found,
        or the string 'No solution' if no such solution exists.
    """
    if a == 0 and b == 0:
        return 'No solution' if n != 0 else ('x = ', 0, ', y = ', 0)
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return ('x = ', 0, ', y = ', n // b)
        else:
            return 'No solution'
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return ('x = ', n // a, ', y = ', 0)
        else:
            return 'No solution'
    max_x = n // a if a != 0 else 0
    for x in range(max_x + 1):
        remainder = n - a * x
        if remainder < 0:
            break
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return ('x = ', x, ', y = ', y)
    return 'No solution'
