def get_total_number_of_sequences(N, K):
    """
    Count the number of ordered sequences of length K composed of positive integers from 1 to N,
    where each term after the first is at least double the previous term.

    Args:
    - N (int): The upper bound for sequence elements (1 to N).
    - K (int): The length of the sequence.

    Returns:
    - int: The total number of valid sequences.
    """
    dp = [[0] * (N + 1) for _ in range(K + 1)]
    for x in range(1, N + 1):
        dp[1][x] = 1
    for i in range(2, K + 1):
        for prev in range(1, N + 1):
            count = dp[i - 1][prev]
            if count == 0:
                continue
            start = 2 * prev
            if start > N:
                continue
            for x in range(start, N + 1):
                dp[i][x] += count
    return sum(dp[K][1:])
```

