def count_list(collection):
    """
    Recursively count all recognized collection types inside the given collection.
    Recognized collection types: list, tuple, dict, set, frozenset.

    Each occurrence of these types counts as 1, including the top-level collection itself.

    Args:
        collection: The input collection to analyze.

    Returns:
        int: The total count of recognized collections found inside.
    """
    recognized_types = (list, tuple, dict, set, frozenset)

    def count_col(obj):
        if not isinstance(obj, recognized_types):
            return 0
        total = 1
        if isinstance(obj, dict):
            for k, v in obj.items():
                total += count_col(k)
                total += count_col(v)
        elif isinstance(obj, (list, tuple, set, frozenset)):
            for item in obj:
                total += count_col(item)
        return total
    return count_col(collection)
