def get_total_number_of_sequences(n, m):
    """
    Returns the number of sequences of length n where:
    - Each element is a positive integer starting from 1 (no zeros).
    - Each nxt element is >= 2 * previous element.
    - Each element is <= m.
    """
    if n == 0:
        return 0
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for x in range(1, m + 1):
        dp[1][x] = 1
    for i in range(2, n + 1):
        prefix = 0
        prefix_dp = [0] * (m + 1)
        for y in range(1, m + 1):
            prefix_dp[y] = prefix_dp[y - 1] + dp[i - 1][y]
        for x in range(1, m + 1):
            max_y = x // 2
            if max_y >= 1:
                dp[i][x] = prefix_dp[max_y]
            else:
                dp[i][x] = 0
    return sum(dp[n][1:])
