    for length in range(1, n + 1, 2):
        for start in range(n - length + 1):
            total_sum += sum(arr[start:start + length])
    return total_sum
```

```python
def sum_column(data, col_index):
    total = 0
    found = False
    for row in data:
        if col_index < len(row):
            total += row[col_index]
            found = True
    return total if found else 0
```

```python
def is_triangleexists(a: int, b: int, c: int) -> bool:
    return a > 0 and b > 0 and (c > 0) and (a + b + c == 180)
