```python
def length_Of_Last_Word(s: str) -> int:
    s = s.rstrip()
    if not s:
        return 0
    words = s.split(' ')
    words = [word for word in words if word]
    if not words:
        return 0
    return len(words[-1])
```

```python
def lcm(a: int, b: int) -> int:
    """Return the least common multiple of two positive integers a and b."""

    def gcd(x: int, y: int) -> int:
        while y:
            x, y = (y, x % y)
        return x
    return a * b // gcd(a, b)
```

